using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.VertexAlgebra.Sectors;

internal sealed class LatticeDualCosetIntertwinerDocument : IScribeDocumentDefinition
{
    private static DocumentBlock D(string selector, string text, DescribeRole role = DescribeRole.Theorem) => Describe.Lean(
        DescribeId.Create("latticedualcosetintertwiner-" + selector.Replace('_', '-').ToLowerInvariant()),
        DeclarationHandle.Create("D5/S3/VertexAlgebra/Sectors/LatticeDualCosetIntertwiner." + selector),
        H(selector), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
        Blocks(Paragraph(Text(text))), role);

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "LatticeDualCosetIntertwiner", H("Full rational Hahn dual-coset fields and derived ground spectrum"), Blocks(
            Paragraph(Text("All entries quantify over arbitrary finite-rank symmetric even integral LatticeData D, including rank zero. Charge D is the original integral charge lattice; Carrier D is the complete finitely supported charge carrier with polynomial oscillators. a,b are integral module parameters, H is a complex matrix, and I is an arbitrary source-linear rational Hahn field. mode(I,u,tau) is raw coefficient -tau-1. Whenever stated, the full hypotheses are Lawful D a b H I, H G_C=1 and G_C H=1, rational mu,nu and exact duality G_Q mu=a, G_Q nu=b. Positivity and integral unimodularity are not assumed. The acting algebra and all module actions, cocycle and original conformal state are the actual native ones.")),
            Paragraph(Text("Classical lattice-fusion conventions follow Bakalov--Kac, math/0402315v1, section 4.1. Imported residue and Pascal suppliers retain Scott Carnahan, ScottCarnahan/vertexAlg revision 4453e34ec390e82a0c789c731ada8f9a6e86bdea; imported Sugawara suppliers retain Kalle Kytölä, VirasoroProject revision 5ff4245383b2cdd4eea7a0524bc1274c32041eb4. Both suppliers retain their Apache-2.0 attributions. These are native applications and proofs of classical mathematics; no literature novelty is claimed.")),
            D("Fields", "Carrier D →ₗ[Complex] HVertexOperator Rational Complex (Carrier D) (Carrier D): the entire source-linear rational Hahn ambient space, with source and input states both arbitrary. No lawful field, nonzero field, prescribed charge support, exponent coset or leading scalar is built into this type.", DescribeRole.Definition),
            D("mode", "For every D,I,u and rational tau, mode I u tau is (I u).coeff(-tau-1), a complex linear endomorphism of the input carrier.", DescribeRole.Definition),
            D("leftTerm", "For arbitrary D,a,I,h,u,v, integers p,r, rational tau and natural i: binomial(p,i) times mode I ((action(a,h)[r+i])u) (p+tau-i) v.", DescribeRole.Definition),
            D("firstTerm", "For arbitrary D,a,b,I,h,u,v,p,r,tau,i: (-1)^i binomial(r,i) times action(a+b,h)[p+r-i] applied to mode I u (tau+i) v.", DescribeRole.Definition),
            D("secondTerm", "For arbitrary D,b,I,h,u,v,p,r,tau,i: (-1)^i binomial(r,i) times the residue sign epsilon(r) times mode I u (tau+r-i) ((action(b,h)[p+i])v). The residue sign is distinct from the lattice cocycle epsilon(D,m,n).", DescribeRole.Definition),
            D("Lawful", "For every source u and rational tau, source L(-1) differentiates the field: mode I (moduleL(a,H,-1)u) tau = -tau times mode I u (tau-1). The target L(-1) commutator equals the same derivative using target a+b and input b. For every algebra state h, source u, input v, integers p,r and rational tau, EACH of leftTerm, firstTerm and secondTerm has finite natural-index support, and sum(leftTerm)=sum(firstTerm)-sum(secondTerm). These are full arbitrary-charged mixed Jacobi laws; there is no charge, exponent-coset or leading-normalization axiom.", DescribeRole.Definition),
            D("operatorSpace", "For every D,a,b,H, the complex submodule of Fields D consisting exactly of Lawful fields. Private lawful_zero, lawful_add and lawful_smul establish closure and are live consumers of the three separate finite-support laws. Closure establishes no nonzero element.", DescribeRole.Definition),
            D("ground", "For every integral charge n, ground D n is Finsupp.single n 1 in the actual carrier; the polynomial has no oscillators.", DescribeRole.Definition),
            D("groundPower", "For every rational mu,nu and integral n,l, groundPower is pairing D (n+mu) (l+nu), with rational coordinates and the original Gram pairing.", DescribeRole.Definition),
            D("groundScalar", "For every D,I,mu,nu,n,l, take the coefficient of I(ground n)(ground l) at raw power groundPower(mu,nu,n,l), then its charge n+l component, then polynomial constantCoeff. No nonvanishing or normalization is assumed.", DescribeRole.Definition),
            D("chargedPower", "For every D and integral d,m,n, chargedPower D d m n = bilinear D m n + sum_i m_i d_i, an integer.", DescribeRole.Definition),
            D("mode_smul_source", "For all D,I, complex c, source u, rational tau and input v, mode I (c smul u) tau v = c smul mode I u tau v. No Lawful or inverse hypotheses. Derived by source linearity. Used by coefficient_charge, charged_source_recurrence and reconstruct_source."),
            D("mode_add_source", "For all D,I,u,w,tau,v, mode I (u+w) tau v is the sum of the two source modes. No Lawful or inverse hypotheses. Derived by source linearity. Used by reconstruct_source and ground_sequence_detects_zero."),
            D("ward", "For every Lawful I, all algebra h, source u, input v, integer p and rational tau: action(a+b,h)[p](mode I u tau v) - mode I u tau(action(b,h)[p]v) = sum_i leftTerm(D,a,I,h,u,v,p,0,tau,i). Set r=0 in full Jacobi; the other binomial sums each collapse to i=0. No inverse or duality hypotheses. Used by ground_current_ward, energy_ward and coefficient_charge."),
            D("current_ground", "For arbitrary integral d,n, colour i and natural j, action(d,currentState i)[j](ground n) equals (bilinear(unitCharge i,n)+d_i) smul ground n if j=0 and zero otherwise. No I, Lawful or inverse hypotheses. Substitute the native current coefficients and differentiate the constant polynomial. Used by ground_current_ward and pair_ground_detects_zero."),
            D("ground_current_ward", "For every Lawful I, integral n, arbitrary input v, colour i, integer p and rational tau, the current commutator on mode I (ground n) tau v equals (bilinear(unitCharge i,n)+a_i) smul mode I (ground n) (p+tau) v. Apply ward and current_ground; all positive source-current terms vanish. No inverse or duality hypotheses. Used by pair_ground_detects_zero and reconstruct_input."),
            D("energy_ward", "For every Lawful I and all u,v,tau, moduleL(a+b,H,0)(mode I u tau v) - mode I u tau(moduleL(b,H,0)v) = mode I (moduleL(a,H,0)u) tau v - (tau+1) smul mode I u tau v. Use ward with the original omega and p=1, then the actual source-translation law. No inverse or duality hypotheses. Used by ground_eigen."),
            D("current_component", "For all D,d,i, integer m, arbitrary carrier v and charge k, the charge k component of action(d,currentState i)[m]v is shiftedCurrentPolynomial D d 1 i k m (v k). The proof extends the native single-charge current formula through finite-support linear induction. No I, Lawful or inverse hypotheses. Used in coefficient_charge and pair_ground_detects_zero."),
            D("coefficient_charge", "For every Lawful I with H G_C=1, integral source/input/output charges n,l,k, arbitrary oscillator polynomials u,v and rational tau, a nonzero charge k component of mode I (single n u) tau (single l v) forces k=n+l. Zero-current Ward identities give all Gram row equations; cancel the nonzero polynomial and apply the original Gram left inverse. No right-inverse, positivity or rational-duality hypothesis. This forces charge support, as used by ground_charge."),
            D("ground_charge", "For every Lawful I with H G_C=1 and every n,l,k,tau, a nonzero charge k component of the ground-to-ground mode forces k=n+l. This is coefficient_charge at the constant source and input polynomials. Used by ground_charge_projection."),
            D("ground_charge_projection", "For every Lawful I with H G_C=1 and all n,l,tau, the whole ground-to-ground mode equals single(n+l, its n+l component). Use ground_charge to eliminate every other charge. No right inverse or rational duality is required. Used by ground_leading and pair_ground_detects_zero."),
            D("ground_energy_difference", "For every D, rational mu,nu and integral n,l, q_(mu+nu)(n+l)-q_mu(n)-q_nu(l)=groundPower(mu,nu,n,l). Expand the original quadratic form using symmetry and bilinearity. No I, inverse or exact-duality hypothesis. Used by ground_spectrum."),
            D("ground_L0", "For every D,H, integral d, both inverse equations, rational mu with G_Q mu=d and integral n, actual moduleL(d,H,0)(ground n)=q_mu(n) smul ground n. Specialize moduleL_basis_zero to oscillator exponent zero. No Lawful field is required. Used by ground_eigen."),
            D("dual_add", "For every D and integral a,b, rational mu,nu with G_Q mu=a and G_Q nu=b, G_Q(mu+nu)=a+b coordinatewise. Distribute the finite sums. No I or inverse hypotheses. Used by ground_spectrum."),
            D("ground_eigen", "Under the full hypotheses, for all n,l and rational raw power s, actual moduleL(a+b,H,0) on (I(ground n)).coeff s (ground l) is multiplication by q_mu(n)+q_nu(l)+s. Apply energy_ward at tau=-s-1 and the two actual ground_L0 equations. The coefficient may be zero. Used by ground_spectrum."),
            D("ground_spectrum", "Under the full hypotheses, for every n,l,k, oscillator exponent e and rational raw power s, a nonzero polynomial coefficient e in charge k of the ground-to-ground field implies BOTH k=n+l and s=groundPower(mu,nu,n,l)+oscillatorEnergy(e). Combine charge selection with actual moduleL_coeff, cancel the nonzero coefficient and use the quadratic energy difference. This derives the rational exponent restriction from the laws. This joint charge/energy restriction is used by ground_below, ground_leading and pair_ground_detects_zero."),
            D("ground_below", "Under the full hypotheses, for all n,l and rational s strictly below groundPower(mu,nu,n,l), the entire raw coefficient is zero. A hypothetical nonzero charge/monomial coefficient contradicts ground_spectrum and nonnegative natural oscillator energy. Used by mode_below and the charged recurrences."),
            D("ground_leading", "Under the full hypotheses, for every n,l, the full raw coefficient at groundPower equals groundScalar(mu,nu,n,l) smul ground(n+l). Charge projection and the spectrum force oscillator energy zero, hence exponent zero. The scalar can vanish. Used by mode_leading and the charged recurrences."),
            D("charged_ground_leading", "For all D and integral d,m,n, the actual charged action at integer mode -chargedPower(d,m,n)-1 sends ground n to epsilon(D,m,n) smul ground(m+n). Compute the native creation coefficient at zero with the original cocycle. No inverse, rational duality or Lawful field hypotheses. Used by charged_source_recurrence and charged_input_recurrence."),
            D("charged_ground_above", "For all D,d,m,n and integer j strictly greater than -chargedPower(d,m,n)-1, the charged action at j on ground n is zero. The native creation index is negative. No inverse, duality or Lawful field hypotheses. Used by both charged recurrences."),
            D("chargedPower_add", "For all D,a,b,m,n,l, chargedPower(a+b,m,n+l)=chargedPower(a,m,n)+chargedPower(b,m,l). Distribute bilinear and coordinate pairings. No I, H or rational duality is required. Used by both charged recurrences."),
            D("groundPower_source_shift", "For all D,b, rational mu,nu with G_Q nu=b, and integral m,n,l, groundPower(mu,nu,m+n,l)=groundPower(mu,nu,n,l)+chargedPower(b,m,l). Expand the rational Gram pairing and use physical_pairing_integral. No inverse or Lawful field hypotheses; no duality assumption on mu. Used by charged_source_recurrence and groundPower_input_shift."),
            D("groundPower_input_shift", "For all D,a, rational mu,nu with G_Q mu=a, and integral m,n,l, groundPower(mu,nu,n,m+l)=groundPower(mu,nu,n,l)+chargedPower(a,m,n). Use groundPower_source_shift with the arguments exchanged and symmetry. No inverse or Lawful field hypotheses; no duality assumption on nu. Used by charged_input_recurrence."),
            Paragraph(Text("coefficient_charge and ground_spectrum supply the charge and energy restrictions used in ground rigidity. The derivation uses source linearity, Ward specializations, quadratic expansion, actual ground L0 specialization, dual addition and charged leading-index formulas in the proofs named above. current_component uses finite-charge induction. Private lawful_zero, lawful_add and lawful_smul establish the closure properties used to define operatorSpace. The module specifies the full-law space and derives constraints on any element. It proves neither the existence of a nonzero lawful field nor a dimension-one equality, categorical fusion equivalence, physical realization or completion of string theory.")))));
}
